import React, { useState } from 'react';
import { Counter } from './Counter';
import { Banner } from './Banner';

export default function App() {
  const [name, setName] = useState('tester');

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: 24, maxWidth: 640 }}>
      <Banner />
      <h1 style={{ marginTop: 16 }}>Hello, {name}!</h1>
      <p style={{ color: '#666' }}>
        If you can read this, the import flow restored both <code>App.tsx</code> and the
        two sibling files (<code>Counter.tsx</code>, <code>Banner.tsx</code>).
      </p>
      <input
        value={name}
        onChange={(e) => setName(e.target.value)}
        style={{ padding: '6px 10px', fontSize: 14, border: '1px solid #ccc', borderRadius: 4 }}
        placeholder="your name"
      />
      <div style={{ marginTop: 24 }}>
        <Counter label="clicks" />
      </div>
    </div>
  );
}

import React, { useState } from 'react';

export function Counter({ label }: { label: string }) {
  const [count, setCount] = useState(0);
  return (
    <button
      onClick={() => setCount((c) => c + 1)}
      style={{
        padding: '8px 16px',
        fontSize: 14,
        background: '#4f46e5',
        color: 'white',
        border: 0,
        borderRadius: 6,
        cursor: 'pointer',
      }}
    >
      {count} {label}
    </button>
  );
}

import React from 'react';

export function Banner() {
  return (
    <div
      style={{
        background: 'linear-gradient(135deg, #4f46e5 0%, #06b6d4 100%)',
        color: 'white',
        padding: '12px 16px',
        borderRadius: 8,
        fontWeight: 600,
        letterSpacing: 0.2,
      }}
    >
      Imported via JSON — schema-reset survivor edition
    </div>
  );
}
